def test_normalize_csv_empty_input():
    result = normalize_csv("")
    assert result == ""


def test_normalize_csv_single_column_fix():
    input_text = '["el libro"]\n["la casa"]'
    expected_result = 'el libro, the book\nla casa, the house'
    # Mock the response from the model to include English translations
    mock_response = 'el libro, the book\nla casa, the house'
    result = normalize_csv(mock_response)
    assert result == expected_result


def test_normalize_csv_header_row_fix():
    input_text = 'spanish,english\n"el libro","the book"\n"la casa","the house"'
    result = normalize_csv(input_text)
    assert result == 'el libro,the book\nla casa,the house'


def test_normalize_csv_more_than_50_cards():
    input_text = '\n'.join(['"el libro","the book"]'] * 51)
    with pytest.raises(ValueError, match="The model returned more than 50 cards."):
        normalize_csv(input_text)


